SELECT budget_bucket, finance_budget FROM (SELECT CASE WHEN budget >= 4282000 THEN 'high' WHEN budget >= 1902000 THEN 'mid' ELSE 'low' END AS budget_bucket, SUM(CASE WHEN dept_name = 'Finance' THEN budget ELSE 0 END) AS finance_budget FROM departments WHERE budget >= 1697000 GROUP BY CASE WHEN budget >= 4282000 THEN 'high' WHEN budget >= 1902000 THEN 'mid' ELSE 'low' END) AS s WHERE finance_budget < 56 ORDER BY finance_budget DESC;
